What does this program print?

```zig
const std = @import("std");

fn demo() void {
    defer std.debug.print("a", .{});
    {
        defer std.debug.print("b", .{});
        std.debug.print("c", .{});
    }
    defer std.debug.print("d", .{});
    std.debug.print("e", .{});
}

pub fn main() void {
    demo();
    std.debug.print("\n", .{});
}
```

What does this program print?

```zig
const std = @import("std");

fn step(fail: bool) !u8 {
    std.debug.print("1", .{});
    errdefer std.debug.print("x", .{});
    defer std.debug.print("2", .{});
    if (fail) return error.Nope;
    return 5;
}

pub fn main() void {
    _ = step(false) catch 0;
    std.debug.print("|", .{});
    _ = step(true) catch 0;
    std.debug.print("\n", .{});
}
```

Using the lesson's `parsePort` and `parseAddress`, what does this loop print?

```zig
for ([_][]const u8{ "a:0", ":443" }) |in| {
    if (parseAddress(in)) |addr| {
        std.debug.print("[{s}]:{d} ", .{ addr.host, addr.port });
    } else |err| {
        std.debug.print("{t} ", .{err});
    }
}
```

What does this program print?

```zig
const std = @import("std");

fn half(x: u32) ?u32 {
    if (x % 2 != 0) return null;
    return x / 2;
}

pub fn main() void {
    const a = half(10) orelse 0;
    const b = half(7) orelse 99;
    const c = if (half(half(12) orelse 1)) |v| v + 100 else 0;
    std.debug.print("{d} {d} {d}\n", .{ a, b, c });
}
```
